def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    items = data.get("items")
    if not isinstance(items, list):
        return False
    ids = [item.get("topicId") for item in items]
    collected = [globalParam.get("it" + str(i)) for i in range(1, 11)]
    collected = [x for x in collected if x is not None]
    ok = statusCode == 200 and responseBody.get("code") == 0 and bool(responseBody.get("requestId"))
    ok = ok and set(ids) == {globalParam.get("t2"), globalParam.get("t3")}
    ok = ok and len(collected) == 3 and len(set(collected)) == 3
    ok = ok and set(collected) == {globalParam.get("t1"), globalParam.get("t2"), globalParam.get("t3")}
    ok = ok and globalParam.get("hm10") is not True
    return ok
